function parseDuration(s: string): number {
  const pattern = /^\d+[hms]?(?:(?:\s+|,\s+)\d+[hms]?)*$/;
  if (!pattern.test(s)) {
    throw new Error(`invalid duration: ${s}`);
  }

  const components = s.match(/\d+[hms]?/g)!;
  let total = 0;

  for (const comp of components) {
    const num = parseInt(comp, 10);
    const unit = comp[comp.length - 1];
    switch (unit) {
      case 'h':
        total += num * 3600;
        break;
      case 'm':
        total += num * 60;
        break;
      case 's':
      default:
        total += num;
        break;
    }
  }

  return total;
}

