function parseDuration(s: string): number {
  const bare = /^\d+$/;
  const full = /^\d+[hms](?:(?:\s+|,\s+)?\d+[hms])*$/;

  if (!bare.test(s) && !full.test(s)) {
    throw new Error(`invalid duration: ${s}`);
  }

  if (bare.test(s)) {
    return parseInt(s, 10);
  }

  const components = s.match(/\d+[hms]/g)!;
  let total = 0;
  for (const comp of components) {
    const num = parseInt(comp.slice(0, -1), 10);
    const unit = comp[comp.length - 1];
    if (unit === 'h') total += num * 3600;
    else if (unit === 'm') total += num * 60;
    else total += num;
  }
  return total;
}

