function parseDuration(s: string): number {
  if (typeof s !== 'string') {
    throw new Error(`invalid duration: ${s}`);
  }

  // Bare number case: entire string is just digits (seconds).
  if (/^\d+$/.test(s)) {
    return parseInt(s, 10);
  }

  // Full pattern: one or more "<number><unit>" tokens, separated by
  // either nothing, plain whitespace, or a comma followed by whitespace.
  const fullPattern = /^\d+[hms](?:(?:,\s+|\s*)\d+[hms])*$/;

  if (s.length === 0 || !fullPattern.test(s)) {
    throw new Error(`invalid duration: ${s}`);
  }

  const tokenRegex = /(\d+)([hms])/g;
  let total = 0;
  let match: RegExpExecArray | null;

  while ((match = tokenRegex.exec(s)) !== null) {
    const value = parseInt(match[1], 10);
    const unit = match[2];

    switch (unit) {
      case 'h':
        total += value * 3600;
        break;
      case 'm':
        total += value * 60;
        break;
      case 's':
        total += value;
        break;
    }
  }

  return total;
}

export { parseDuration };

export function parseDuration(s: string): number {
  const orig = s;
  const len = s.length;
  let i = 0;
  let total = 0;
  let count = 0;
  let missingUnit = false;

  while (i < len) {
    if (count > 0) {
      const sepMatch = /^(?:,\s+|\s+)/.exec(s.slice(i));
      if (sepMatch) {
        i += sepMatch[0].length;
      }
    }

    const numMatch = /^\d+/.exec(s.slice(i));
    if (!numMatch) {
      throw new Error(`invalid duration: ${orig}`);
    }
    const numStr = numMatch[0];
    i += numStr.length;

    let unit: string | null = null;
    const unitMatch = /^[hms]/.exec(s.slice(i));
    if (unitMatch) {
      unit = unitMatch[0];
      i += 1;
    } else {
      missingUnit = true;
    }

    const value = parseInt(numStr, 10);
    let factor = 1;
    if (unit === 'h') {
      factor = 3600;
    } else if (unit === 'm') {
      factor = 60;
    } else if (unit === 's') {
      factor = 1;
    }

    total += value * factor;
    count++;
  }

  if (count === 0) {
    throw new Error(`invalid duration: ${orig}`);
  }

  if (count > 1 && missingUnit) {
    throw new Error(`invalid duration: ${orig}`);
  }

  return total;
}
